const KEY='neuvetra-company-intake-preview-v1';
const titles=['Company','Reporting period','Entities & boundary','Locations','Changes & shared operations','Source activities','Review'];
const families=[['Heating & process equipment','Boilers, furnaces, ovens or other equipment that burns fuel.'],['Backup generators','Fuel-powered generators, including equipment used only in emergencies.'],['Road & off-road vehicles','Company-controlled cars, trucks, forklifts or other mobile equipment.'],['Cooling & fire suppression','Refrigeration, air-conditioning or fire suppression systems that may release gases.'],['Processes & other direct releases','Manufacturing reactions, industrial gas use or other direct releases.']];
const changes=['Acquisitions or disposals','Site openings or closures','Changes in ownership or control','Joint ventures or shared operations','Franchises, outsourcing or leased assets'];
const blank=()=>({company:{},period:{},boundary:{},entities:[],locations:[],changes:changes.map(()=>({})),sources:families.map(()=>({})),review:{}});
let data=blank(),step=0,all=false,storageOK=true;
function validDraft(d){return CompanyValidation.draftSchema.safeParse(d).success;}
function activeFields(label,obj){const copy={...obj};if(label==='Company'&&copy.industry!=='Other')delete copy.other;if(label==='Period'&&copy.first!=='No')delete copy.base;if(label==='Boundary'&&copy.hasParent!=='Yes')delete copy.parent;if(label.startsWith('Location'))return locationSummary(obj);if(changes.includes(label)&&!['Yes','Not sure'].includes(copy.answer)){delete copy.date;delete copy.details;}if(families.some(f=>f[0]===label)&&!['Yes','Not sure'].includes(copy.answer)){delete copy.names;delete copy.location;delete copy.notes;}return copy;}
const fieldNames={legal:'Legal name',trading:'Trading name',country:'Country',region:'City / region',industry:'Business activity',other:'Other activity',additional:'Additional business activities',naics:'NAICS code (2022)',role:'Preparer role',start:'Period start',end:'Period end',first:'First inventory',base:'Prior inventory / base year',hasParent:'Has a parent',parent:'Parent company',approach:'Proposed approach',operations:'Included operations',name:'Name',relationship:'Relationship',owner:'Parent / owner',share:'Ownership share (%)',included:'Proposed inclusion',reason:'Reason',purpose:'Purpose',entity:'Owning / operating entity',otherEntity:'Other entity',occupancy:'Occupancy',control:'Equipment control',operator:'Control details',locality:'Address / identifying locality',startMode:'Coverage start status',endMode:'Coverage end status',opened:'Original site opening date',from:'Coverage start date',to:'Active through within reporting period',answer:'Answer',date:'Effective date',details:'Details',names:'Equipment / activity names',location:'Location',notes:'Notes'};
try{const saved=localStorage.getItem(KEY);if(saved){const parsed=JSON.parse(saved);if(parsed.version!==1||!validDraft(parsed.data))throw Error();data={...blank(),...parsed.data};}}catch{data=blank();storageOK=false;}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const get=p=>p.split('.').reduce((o,k)=>o?.[k],data)??'';
function put(p,v){const ks=p.split('.');let o=data;ks.slice(0,-1).forEach(k=>o=o[k]);o[ks.at(-1)]=v;}
function save(){try{localStorage.setItem(KEY,JSON.stringify({version:1,data}));storageOK=true;}catch{storageOK=false;}document.querySelector('#saved').textContent=storageOK?'Changes saved on this device':'Changes could not be saved on this device';const error=document.querySelector('#save-error');if(error){error.hidden=storageOK;error.textContent=storageOK?'':'Your changes could not be saved on this device. Keep this page open to avoid losing information.'}}
if(ensureLocationIds())save();
function field(label,path,options=null,type='text',hint='',full=false){const v=get(path);return `<label class="field ${full?'full':''}">${label}${options?`<select data-path="${path}"><option value="">Select an answer</option>${options.map(x=>{const value=Array.isArray(x)?x[0]:x,label=Array.isArray(x)?x[1]:x;return `<option ${v===value?'selected':''} value="${esc(value)}">${esc(label)}</option>`;}).join('')}</select>`:type==='textarea'?`<textarea data-path="${path}">${esc(v)}</textarea>`:`<input data-path="${path}" type="${type}" value="${esc(v)}" ${type==='number'?'min="0" max="100" step="any"':''}>`}${hint?`<small>${hint}</small>`:''}</label>`;}
function choices(label,path){return `<fieldset style="border:0;padding:0;margin:0"><legend>${label}</legend><div class="choices">${['Yes','No','Not sure'].map(x=>`<label><input type="radio" name="${path}" data-path="${path}" value="${x}" ${get(path)===x?'checked':''}>${x}</label>`).join('')}</div></fieldset>`;}
const grid=x=>`<div class="grid">${x}</div>`;
const note=x=>`<div class="hint">${x}</div>`;
const inclusion=['Include','Exclude — review needed','Not sure'];
function section(n,body,lead){return `<section class="section" data-section="${n}"><h2 tabindex="-1">${String(n+1).padStart(2,'0')} / ${titles[n]}</h2><p class="lead">${lead}</p>${body}</section>`;}
function renderSection(n){
if(n===0)return companySection();
if(n===1)return section(n,note('2025 is the proposed first supported reporting year. Other years and non-calendar periods can be captured here, but need review before calculation support is determined.')+grid(field('Reporting period start','period.start',null,'date')+field('Reporting period end','period.end',null,'date'))+`<button type="button" data-action="year" style="margin:18px 0">Use calendar year 2025</button>`+grid(field('Is this your first inventory?','period.first',['Yes','No','Not sure'])+(get('period.first')==='No'?field('Prior inventory / base-year reference (optional)','period.base',null,'text','Year or a short description; do not upload documents.'):'')),'Choose exact dates. Nothing is assumed from the current calendar year.');
if(n===2)return section(n,grid(field('Does the reporting company have a parent?','boundary.hasParent',['Yes','No','Not sure'])+(get('boundary.hasParent')==='Yes'?field('Parent company name','boundary.parent'):'')+field('Proposed consolidation approach','boundary.approach',['Operational control','Financial control','Equity share','Not sure']))+note('Operational control considers authority to introduce and implement operating policies. Financial control considers the ability to direct financial and operating policies for economic benefit. Equity share reflects economic interest. This selection is a proposal for an authorized reviewer, not a confirmed boundary.')+field('Operations you intend to include','boundary.operations',null,'textarea','Describe the group or business units, including any proposed exclusions.')+data.entities.map((e,i)=>`<div class="card"><div class="cardhead"><h3>Related entity ${i+1}</h3><button type="button" data-remove="entities" data-index="${i}">Remove entity</button></div>${grid(field('Entity legal name',`entities.${i}.name`)+field('Relationship',`entities.${i}.relationship`,['Subsidiary','Joint venture','Affiliate','Other','Not sure'])+field('Direct parent / owner',`entities.${i}.owner`)+field('Ownership share (%) — optional',`entities.${i}.share`,null,'number','Leave blank if not known.')+field('Included in proposed inventory?',`entities.${i}.included`,inclusion)+field('Inclusion / exclusion reason',`entities.${i}.reason`))}</div>`).join('')+`<button type="button" data-add="entities">+ Add subsidiary or related entity</button>`+sourcesHelp(),'Map the corporate structure. Add each related entity; do not assume ownership alone settles control.');
if(n===3)return locationSection();
if(n===4)return section(n,changes.map((c,i)=>`<div class="card">${choices(c,`changes.${i}.answer`)}${get(`changes.${i}.answer`)==='Yes'||get(`changes.${i}.answer`)==='Not sure'?grid(field('Effective date (if known)',`changes.${i}.date`,null,'date')+field('Affected entities / locations and details',`changes.${i}.details`,null,'textarea'))+note('Captured for review. Changes and complex arrangements are not automatically resolved by this beta.'):''}</div>`).join(''),'Consider the whole reporting period. Include arrangements that may change who controls an operation.');
if(n===5)return section(n,note('These questions identify possible source families. A “Yes” does not mean a calculation method is supported or released. Quantities, fuel details and documents come later.')+families.map(([name,help],i)=>`<div class="card"><h3>${name}</h3><p class="lead">${help}</p>${choices('Does this apply within your proposed boundary?',`sources.${i}.answer`)}${['Yes','Not sure'].includes(get(`sources.${i}.answer`))?grid(field('Equipment / activity names (if known)',`sources.${i}.names`,null,'textarea','List a few names, or describe what needs checking.')+field('Location',`sources.${i}.location`,[...data.locations.map((l,i)=>[l.id,locationChoiceLabel(l,i)]),'Multiple locations — describe below','Not sure'])+field('Location details / other notes',`sources.${i}.notes`,null,'textarea'))+note('Applicability recorded; calculation support requires separate review.'):''}</div>`).join('')+`<details><summary>Why these source families?</summary><p>Screening follows the EPA’s stationary combustion, mobile, fugitive and process categories. <a href="https://www.epa.gov/climateleadership/determine-emissions-sources" target="_blank" rel="noreferrer">Read EPA source guidance ↗</a></p></details>`,'Think about activities, not gas codes. Answer each family; unanswered questions are never treated as “No”.');
const issues=validate();return section(n,`<div class="summary"><div><small>REPORTING COMPANY</small><strong>${esc(get('company.legal')||'Not answered')}</strong><small>${esc(get('company.country')||'Country not answered')}</small></div><div><small>PERIOD</small><strong>${esc(get('period.start')||'Not answered')} → ${esc(get('period.end')||'Not answered')}</strong></div><div><small>PROPOSED BOUNDARY</small><strong>${esc(get('boundary.approach')||'Not answered')}</strong><small>${data.entities.length} related entities · ${data.locations.length} locations captured</small></div><div><small>SOURCE SCREENING</small><strong>${data.sources.filter(s=>s.answer==='Yes').length} yes · ${data.sources.filter(s=>s.answer==='No').length} no</strong><small>${data.sources.filter(s=>!s.answer||s.answer==='Not sure').length} unanswered / uncertain families</small></div></div><h3>Items to resolve</h3>${issues.length?`<ul class="issues">${issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:note('Core intake questions are answered. An authorized reviewer still needs to review the proposed boundary and support limits.')}<details open><summary>Everything captured · edit any section from the navigation</summary>${titles.slice(0,6).map((t,i)=>`<h3>${t} <button type="button" data-edit="${i}" class="text">Edit</button></h3>${reviewText(i)}`).join('')}</details><label class="check"><input type="checkbox" data-path="review.complete" ${data.review.complete?'checked':''}>I have listed the entities, locations and source types to the best of my knowledge, with uncertainties identified.</label>${field('Authorized boundary reviewer role','review.role',null,'text','Required before a boundary can be approved. No personal details needed.')}<label class="check"><input type="checkbox" data-path="review.needed" ${data.review.needed?'checked':''}>I understand an authorized reviewer must review the proposed boundary and open items.</label>${note('This records a local draft acknowledgment only. It is not professional assurance, boundary approval, an emissions result or permission to release an inventory.')}<p id="review-result" role="status"></p>`,'Review the proposed business setup. Missing answers and unsupported cases remain visible.');
}
function sourcesHelp(){return `<details><summary>Boundary guidance and sources</summary><p>Plain-language summaries are based on <a target="_blank" rel="noreferrer" href="https://www.epa.gov/climateleadership/determine-organizational-boundaries">EPA organizational boundary guidance ↗</a> and the <a target="_blank" rel="noreferrer" href="https://ghgprotocol.org/corporate-standard">GHG Protocol Corporate Standard, chapter 3 ↗</a>. Selecting an approach here does not determine exhaustive compliance.</p></details>`;}
function validate(){const a=[];const req=(p,label)=>{if(!String(get(p)).trim())a.push(label+' is not answered.');else if(get(p)==='Not sure')a.push(label+' is uncertain.');};Object.entries(companyErrors(data.company)).forEach(([k,v])=>a.push(COMPANY_FIELDS[k].label+': '+v));req('period.start','Period start');req('period.end','Period end');req('period.first','First inventory');if(get('period.start')&&get('period.end')&&get('period.end')<get('period.start'))a.push('Reporting period ends before it starts.');if(get('period.start')&&get('period.end')&&(get('period.start')!=='2025-01-01'||get('period.end')!=='2025-12-31'))a.push('This reporting period needs support review; calendar 2025 is the proposed initial scope.');req('boundary.hasParent','Parent relationship');if(get('boundary.hasParent')==='Yes')req('boundary.parent','Parent name');req('boundary.approach','Consolidation approach');req('boundary.operations','Included operations');if(['Financial control','Equity share'].includes(get('boundary.approach')))a.push('Financial control / equity share needs support and authorized boundary review.');data.entities.forEach((e,i)=>{['name','relationship','owner','included','reason'].forEach(k=>req(`entities.${i}.${k}`,`Entity ${i+1}: ${k}`));if(e.share!==''&&e.share!=null&&(Number(e.share)<0||Number(e.share)>100))a.push(`Entity ${i+1}: ownership share must be 0–100%.`);if(!e.share)a.push(`Entity ${i+1}: ownership share is not provided; review relationship.`);if(e.included?.startsWith('Exclude'))a.push(`Entity ${i+1}: proposed exclusion needs review.`);});a.push(...locationOpenItems());data.changes.forEach((c,i)=>{req(`changes.${i}.answer`,changes[i]);if(['Yes','Not sure'].includes(c.answer)){a.push(changes[i]+': retained for boundary/support review.');req(`changes.${i}.details`,changes[i]+' details');if(!c.date)a.push(changes[i]+': effective date not provided.');}});data.sources.forEach((s,i)=>{req(`sources.${i}.answer`,families[i][0]);if(['Yes','Not sure'].includes(s.answer)){if(!s.names)a.push(families[i][0]+': equipment names/details still needed.');req(`sources.${i}.location`,families[i][0]+' location');if(s.location&&!['Not sure','Multiple locations — describe below',...data.locations.map(l=>l.id)].includes(s.location))a.push(families[i][0]+': linked location was removed or is ambiguous; update the link.');if(s.location==='Multiple locations — describe below'&&!s.notes)a.push(families[i][0]+': list the linked locations in notes.');a.push(families[i][0]+': calculation eligibility not established.');}});return a;}
function reviewText(i){const groups=[{Company:data.company},{Period:data.period},{Boundary:data.boundary,...Object.fromEntries(data.entities.map((e,n)=>['Entity '+(n+1),e]))},Object.fromEntries(data.locations.map((l,n)=>['Location '+(n+1),l])),Object.fromEntries(data.changes.map((c,n)=>[changes[n],c])),Object.fromEntries(data.sources.map((s,n)=>[families[n][0],s]))];return Object.entries(groups[i]).map(([label,obj])=>`<div class="hint"><strong>${esc(label)}</strong><br>${Object.entries(activeFields(label,obj)).filter(([k])=>k!=='id').map(([k,v])=>`${esc(fieldNames[k]||k)}: ${esc((k==='location'?sourceLocationLabel(v):v)||'Not answered')}`).join('<br>')||'Not answered'}</div>`).join('')||'<p>None captured — not a completeness claim.</p>';}
function render(focus=false){document.querySelector('#steps').innerHTML=titles.map((t,i)=>`<button type="button" data-step="${i}" ${step===i&&!all?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span>${t}</button>`).join('');document.querySelector('#questions').innerHTML=all?titles.map((_,i)=>renderSection(i)).join(''):renderSection(step);document.querySelector('#mode').textContent=all?'Return to guided setup':'View all questions';document.querySelector('#back').disabled=!all&&step===0;document.querySelector('#next').textContent=all||step===6?'Save review acknowledgment':'Continue →';document.querySelector('#stepcount').textContent=all?'All questions':`${step+1} of 7`;if(!storageOK){document.querySelector('#saved').textContent='Saved information could not be restored';const error=document.querySelector('#save-error');if(error&&error.hidden){error.hidden=false;error.textContent='Saved information could not be restored. Keep this page open while you check the information.'}}if(focus){document.querySelector('.section h2').focus();document.querySelector('#questions').scrollIntoView({block:'start'});}}
document.addEventListener('input',e=>{const p=e.target.dataset.path;if(!p)return;put(p,e.target.type==='checkbox'?e.target.checked:e.target.value);if(!p.startsWith('review.')){data.review.complete=false;data.review.needed=false;}save();if(p.startsWith('company.'))refreshCompanyErrors();if(p.startsWith('locations.'))refreshLocationErrors();});
document.addEventListener('change',e=>{const p=e.target.dataset.path;if(all&&p&&e.target.tagName!=='SELECT'&&e.target.type!=='radio'){const review=document.querySelector('[data-section="6"]');if(review&&!p.startsWith('review.'))review.outerHTML=renderSection(6);}if(p&&(e.target.tagName==='SELECT'||e.target.type==='radio')){const val=e.target.value;render();const candidates=[...document.querySelectorAll('[data-path]')];candidates.find(x=>x.dataset.path===p&&(x.type!=='radio'||x.value===val))?.focus();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.step!=null||b.dataset.edit!=null){step=Number(b.dataset.step??b.dataset.edit);all=false;render(true);}if(b.dataset.add){data[b.dataset.add].push(b.dataset.add==='locations'?{id:'loc-'+crypto.randomUUID()}:{});data.review={};save();render();document.querySelector(`[data-path="${b.dataset.add}.${data[b.dataset.add].length-1}.name"]`)?.focus();}if(b.dataset.remove){data[b.dataset.remove].splice(Number(b.dataset.index),1);data.review={};save();render();document.querySelector(`[data-add="${b.dataset.remove}"]`)?.focus();}if(b.dataset.action==='year'){data.period.start='2025-01-01';data.period.end='2025-12-31';data.review={};save();render();}});
document.querySelector('#mode').onclick=()=>{all=!all;render(true);};
document.querySelector('#back').onclick=()=>{all=false;step=Math.max(0,step-1);render(true);};
document.querySelector('#next').onclick=()=>{if(!all&&step===0&&Object.keys(companyErrors(data.company)).length){companyAttempted=true;render();document.querySelector('#company-errors').focus();return;}if(!all&&step===3&&locationPageErrors().length){locationsAttempted=true;render();document.querySelector('#locations-errors').focus();return;}if(!all&&step<6){if(step===0){const accepted=CompanyValidation.parseCompany(data.company);if(accepted.success){data.company=accepted.data;save();}}step++;render(true);}else{save();document.querySelector('#review-result').textContent=!storageOK?'Draft could not be saved. Browser storage is unavailable.':data.review.complete&&data.review.needed&&data.review.role?'Acknowledgment saved locally. '+validate().length+' open items remain; authorized review is still required.':'Please complete both acknowledgments and enter the authorized reviewer role. Your incomplete draft is saved locally.';}};
document.querySelector('#reset').onclick=()=>document.querySelector('#reset-dialog').showModal();document.querySelector('#cancel-reset').onclick=()=>document.querySelector('#reset-dialog').close();document.querySelector('#confirm-reset').onclick=()=>{data=blank();step=0;all=false;companyAttempted=false;companyTouched.clear();locationsAttempted=false;locationTouched.clear();naicsQuery='';naicsPage=0;naicsOpen=false;save();document.querySelector('#reset-dialog').close();render(true);};document.querySelector('#form').onsubmit=e=>e.preventDefault();render();

'use strict';
const test=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const vm=require('node:vm');
const {webcrypto}=require('node:crypto');

const root=__dirname;

function element(){
 return {dataset:{},style:{},classList:{add(){},remove(){}},children:[],hidden:false,disabled:false,textContent:'',innerHTML:'',value:'',files:[],
  setAttribute(){},removeAttribute(){},focus(){},scrollIntoView(){},showModal(){},close(){},after(){},append(){},replaceChildren(){},
  querySelector(){return element()},querySelectorAll(){return []},closest(){return null}};
}

test('the complete setup page restores, migrates, and edits a saved legal-name location',async()=>{
 const legal='Example, Inc.';
 const saved={company:{legal,trading:'Example',country:'United States',industry:'Utilities'},period:{start:'2025-01-01',end:'2025-12-31',first:'Yes'},boundary:{hasParent:'No',approach:'Operational control',operations:'All operations'},entities:[],locations:[{name:'Main depot',country:'United States',locality:'Oakland, CA',purpose:'Fleet base',entity:legal,occupancy:'Owned',control:'Reporting company',operator:'Example operations',included:'Include',reason:'Operated by reporting company',startMode:'Active before reporting period',endMode:'Still active'}],changes:Array.from({length:5},()=>({answer:'No'})),sources:Array.from({length:5},()=>({answer:'No'})),review:{}};
 const listeners={};
 const elements=new Map();
 const document={
  querySelector(selector){if(!elements.has(selector))elements.set(selector,element());return elements.get(selector)},
  querySelectorAll(){return []},createElement(){return element()},
  addEventListener(type,handler){(listeners[type]??=[]).push(handler)}
 };
 const storage=new Map([['neuvetra-company-intake-preview-v1',JSON.stringify({version:1,data:saved})]]);
 const context=vm.createContext({console,document,crypto:webcrypto,structuredClone,confirm:()=>true,location:{assign(){}},
  localStorage:{getItem:key=>storage.get(key)??null,setItem:(key,value)=>storage.set(key,value),removeItem:key=>storage.delete(key)},
  fetch:async()=>({ok:true,json:async()=>({revision:1,onboarding:saved,plan:{}})}),setTimeout,clearTimeout,URL,Blob,btoa:value=>Buffer.from(value,'binary').toString('base64')});
 context.window=context;
 const html=fs.readFileSync(path.join(root,'index.html'),'utf8');
 const scripts=[...html.matchAll(/<script\s+src="([^"]+)"/g)].map(match=>match[1]);
 assert.deepEqual(scripts,['validation.bundle.js','company.js','locations.js','app.js','bridge.js']);
 for(const script of scripts)vm.runInContext(fs.readFileSync(path.join(root,script),'utf8'),context,{filename:script});
 assert.match(elements.get('#steps').innerHTML,/Company/);
 assert.match(elements.get('#questions').innerHTML,/Legal company name/);
 let location=JSON.parse(vm.runInContext('JSON.stringify(data.locations[0])',context));
 assert.match(location.id,/^loc-/);
 assert.equal(location.entity,'Reporting company');
 assert.equal(location.originalEntity,legal);
 assert.equal(JSON.parse(storage.get('neuvetra-company-intake-preview-v1')).data.locations.length,1);
 for(const handler of listeners.input||[])handler({target:{dataset:{path:'locations.0.name'},type:'text',value:'Updated depot'}});
 location=JSON.parse(vm.runInContext('JSON.stringify(data.locations[0])',context));
 assert.equal(location.name,'Updated depot');
 assert.equal(JSON.parse(storage.get('neuvetra-company-intake-preview-v1')).data.locations[0].name,'Updated depot');
});

(function (root, factory) {
  const api = factory();
  if (typeof module === 'object' && module.exports) module.exports = api;
  root.PlanCore = api;
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {
  'use strict';

  const SCHEMA_VERSION = 1;
  const SOURCE_FAMILY_IDS = ['stationary', 'generator', 'mobile', 'fugitive', 'process'];
  const VALID_STATUSES = new Set(['not-started', 'in-progress', 'complete']);
  const VALID_QUALITIES = new Set(['actual', 'estimated', 'unknown']);
  const RECORD_FUEL_TYPES = Object.freeze(['natural-gas', 'gasoline', 'diesel', 'propane', 'fuel-oil', 'other', 'not-a-fuel-record', 'unknown']);
  const VALID_RECORD_FUEL_TYPES = new Set(RECORD_FUEL_TYPES);
  const VALID_LOCATION_MODES = new Set(['sites', 'company-wide', 'unknown']);
  const SOURCE_LOCATION_SENTINELS = new Set(['', 'Not sure', 'Multiple locations — describe below']);
  const UNIT_ALIASES = Object.freeze({
    therms: 'therm',
    gal: 'US gallon',
    gallons: 'US gallon'
  });
  const COMPANY_WIDE_SCOPE3 = new Set([
    'category-1', 'category-2', 'category-3', 'category-4', 'category-5', 'category-6',
    'category-7', 'category-9', 'category-10', 'category-11', 'category-12', 'category-15'
  ]);
  const FALLBACK_FAMILIES = {
    stationary: {
      title: 'Heating & process equipment',
      description: 'Boilers, furnaces, ovens or other equipment that burns fuel.'
    },
    generator: {
      title: 'Backup generators',
      description: 'Fuel-powered generators, including equipment used only in emergencies.'
    },
    mobile: {
      title: 'Road & off-road vehicles',
      description: 'Company-controlled cars, trucks, forklifts or other mobile equipment.'
    },
    fugitive: {
      title: 'Cooling & fire suppression',
      description: 'Refrigeration, air-conditioning or fire suppression systems that may release gases.'
    },
    process: {
      title: 'Processes & other direct releases',
      description: 'Manufacturing reactions, industrial gas use or other direct releases.'
    }
  };

  function isObject(value) {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
  }

  function asObject(value) {
    return isObject(value) ? value : {};
  }

  function asArray(value) {
    return Array.isArray(value) ? value : [];
  }

  function text(value) {
    return value == null ? '' : String(value);
  }

  function clone(value) {
    if (value == null) return value;
    return JSON.parse(JSON.stringify(value));
  }

  function stableSerialize(value) {
    if (Array.isArray(value)) return '[' + value.map(stableSerialize).join(',') + ']';
    if (isObject(value)) {
      return '{' + Object.keys(value).sort().map(function (key) {
        return JSON.stringify(key) + ':' + stableSerialize(value[key]);
      }).join(',') + '}';
    }
    if (value === undefined) return 'null';
    return JSON.stringify(value);
  }

  // FNV-1a is used as a compact change detector, not as a security primitive.
  function fingerprint(value, prefix) {
    const input = stableSerialize(value);
    let hash = 0x811c9dc5;
    for (let index = 0; index < input.length; index += 1) {
      hash ^= input.charCodeAt(index);
      hash = Math.imul(hash, 0x01000193);
    }
    return (prefix || 'fp') + '-' + (hash >>> 0).toString(16).padStart(8, '0');
  }

  function normalizedContext(onboarding) {
    const input = asObject(onboarding);
    const company = asObject(input.company);
    const period = asObject(input.period);
    return {
      legal: text(company.legal).trim().toLowerCase(),
      country: text(company.country).trim().toLowerCase(),
      start: text(period.start).trim(),
      end: text(period.end).trim()
    };
  }

  function contextKey(onboarding) {
    return fingerprint(normalizedContext(onboarding), 'ctx');
  }

  function onboardingFingerprint(onboarding) {
    const input = asObject(onboarding);
    return fingerprint({
      company: asObject(input.company),
      period: asObject(input.period),
      boundary: asObject(input.boundary),
      entities: asArray(input.entities),
      locations: asArray(input.locations),
      changes: asArray(input.changes),
      sources: asArray(input.sources)
    }, 'onboarding');
  }

  function normalizeAnswer(value) {
    return value === 'Yes' || value === 'No' || value === 'Not sure' ? value : '';
  }

  function normalizeCatalogList(value) {
    return asArray(value).map(function (entry) { return clone(asObject(entry)); });
  }

  function normalizeCatalogEntry(entry, fallback) {
    const value = asObject(entry);
    const defaultValue = asObject(fallback);
    return {
      id: text(value.id || defaultValue.id),
      title: text(value.title || defaultValue.title),
      description: text(value.description || defaultValue.description),
      checklist: normalizeCatalogList(value.checklist),
      records: normalizeCatalogList(value.records),
      subtypes: normalizeCatalogList(value.subtypes),
      sourceIds: asArray(value.sourceIds).map(text)
    };
  }

  function familyCatalog(catalog) {
    const byId = new Map();
    asArray(asObject(catalog).families).forEach(function (family) {
      const normalized = normalizeCatalogEntry(family);
      if (normalized.id) byId.set(normalized.id, normalized);
    });
    return SOURCE_FAMILY_IDS.map(function (id) {
      return byId.get(id) || normalizeCatalogEntry({ id: id }, FALLBACK_FAMILIES[id]);
    });
  }

  function scopeCatalog(catalog, scope) {
    const key = scope === '2' ? 'scope2' : 'scope3';
    return asArray(asObject(catalog)[key]).map(function (entry) {
      return normalizeCatalogEntry(entry);
    }).filter(function (entry) { return Boolean(entry.id); });
  }

  function locationsById(onboarding) {
    const map = new Map();
    asArray(asObject(onboarding).locations).forEach(function (location) {
      const value = clone(asObject(location));
      const id = text(value.id);
      if (id && !map.has(id)) map.set(id, value);
    });
    return map;
  }

  function sourceLocationIds(source, locationMap) {
    const location = text(asObject(source).location);
    if (SOURCE_LOCATION_SENTINELS.has(location)) return [];
    return locationMap.has(location) ? [location] : [];
  }

  function screeningSeed(catalog, existing) {
    const next = clone(asObject(existing)) || {};
    familyCatalog(catalog).forEach(function (entry) {
      const key = 'scope1:' + entry.id;
      const current = asObject(next[key]);
      next[key] = {
        ...current,
        reason: text(current.reason),
        notes: text(current.notes)
      };
    });
    ['2', '3'].forEach(function (scope) {
      scopeCatalog(catalog, scope).forEach(function (entry) {
        const current = asObject(next[entry.id]);
        const locationIds = asArray(current.locationIds).map(text).filter(Boolean);
        const migrateCompanyWideDefault = scope === '3' && COMPANY_WIDE_SCOPE3.has(entry.id) && current.locationMode === 'sites' && locationIds.length === 0;
        next[entry.id] = {
          ...current,
          answer: normalizeAnswer(current.answer),
          reason: text(current.reason),
          notes: text(current.notes),
          locationIds: locationIds,
          locationMode: migrateCompanyWideDefault
            ? 'company-wide'
            : VALID_LOCATION_MODES.has(current.locationMode)
            ? current.locationMode
            : scope === '3' && COMPANY_WIDE_SCOPE3.has(entry.id) ? 'company-wide' : 'sites'
        };
      });
    });
    return next;
  }

  function mergedChecklist(template, subtypeId) {
    const ordered = [];
    const positions = new Map();
    function add(check) {
      const value = clone(asObject(check));
      const id = text(value.id);
      if (!id) return;
      value.id = id;
      if (positions.has(id)) ordered[positions.get(id)] = value;
      else {
        positions.set(id, ordered.length);
        ordered.push(value);
      }
    }
    asArray(template.checklist).forEach(add);
    const subtype = asArray(template.subtypes).find(function (entry) {
      return text(asObject(entry).id) === text(subtypeId);
    });
    if (subtype) asArray(asObject(subtype).checklist).forEach(add);
    return ordered;
  }

  function baseState(id, seed, locationIds, locationMode) {
    const current = asObject(seed);
    return {
      ...clone(current),
      id: id,
      status: VALID_STATUSES.has(current.status) ? current.status : 'not-started',
      needsReview: current.needsReview === true,
      inputFingerprint: text(current.inputFingerprint),
      subtypeId: text(current.subtypeId),
      locationMode: VALID_LOCATION_MODES.has(current.locationMode)
        ? current.locationMode
        : VALID_LOCATION_MODES.has(locationMode) ? locationMode : 'sites',
      locationIds: Object.prototype.hasOwnProperty.call(current, 'locationIds') && Array.isArray(current.locationIds)
        ? current.locationIds.map(text).filter(Boolean)
        : asArray(locationIds).map(text).filter(Boolean),
      checks: clone(asObject(current.checks)) || {},
      notes: text(current.notes),
      records: clone(asArray(current.records))
    };
  }

  function catalogTemplateFields(entry) {
    return {
      title: text(entry.title),
      description: text(entry.description),
      checklist: clone(asArray(entry.checklist)),
      recordTypes: clone(asArray(entry.records)),
      subtypes: clone(asArray(entry.subtypes)),
      sourceIds: clone(asArray(entry.sourceIds))
    };
  }

  function buildTemplates(onboarding, plan, catalog) {
    const input = asObject(onboarding);
    const state = asObject(plan);
    const locationMap = locationsById(input);
    const templates = [];

    familyCatalog(catalog).forEach(function (family, index) {
      const source = clone(asObject(asArray(input.sources)[index]));
      const answer = normalizeAnswer(source.answer);
      if (answer === 'No') return;
      templates.push({
        id: 'scope1:' + family.id,
        scope: '1',
        familyId: family.id,
        answer: answer,
        kind: answer === 'Yes' ? 'inventory' : 'clarification',
        source: {
          names: text(source.names),
          notes: text(source.notes),
          location: text(source.location)
        },
        seedLocationIds: sourceLocationIds(source, locationMap),
        seedLocationMode: 'sites',
        catalog: family
      });
    });

    ['2', '3'].forEach(function (scope) {
      scopeCatalog(catalog, scope).forEach(function (entry) {
        const screening = asObject(asObject(state.screening)[entry.id]);
        const answer = normalizeAnswer(screening.answer);
        if (answer === 'No' || answer === '') return;
        templates.push({
          id: 'scope' + scope + ':' + entry.id,
          scope: scope,
          screeningId: entry.id,
          answer: answer,
          kind: answer === 'Yes' ? 'inventory' : 'clarification',
          source: null,
          seedLocationIds: asArray(screening.locationIds).map(text).filter(Boolean),
          seedLocationMode: VALID_LOCATION_MODES.has(screening.locationMode) ? screening.locationMode : 'sites',
          catalog: entry
        });
      });
    });

    asArray(state.custom).forEach(function (raw, index) {
      const custom = clone(asObject(raw));
      const customId = text(custom.id) || 'missing-' + index;
      const family = familyCatalog(catalog).find(function (entry) {
        return entry.id === text(custom.familyId);
      });
      const customCatalog = family || normalizeCatalogEntry({
        id: text(custom.familyId),
        title: text(custom.title),
        description: text(custom.description)
      });
      templates.push({
        id: 'custom:' + customId,
        scope: ['1', '2', '3'].includes(text(custom.scope)) ? text(custom.scope) : 'unknown',
        familyId: text(custom.familyId),
        customId: customId,
        answer: 'Yes',
        kind: 'custom',
        source: null,
        seedLocationIds: asArray(custom.locationIds).map(text).filter(Boolean),
        seedLocationMode: VALID_LOCATION_MODES.has(custom.locationMode) ? custom.locationMode : 'sites',
        catalog: {
          ...customCatalog,
          title: text(custom.title) || customCatalog.title,
          description: text(custom.description) || customCatalog.description
        },
        custom: custom
      });
    });
    return templates;
  }

  function itemFingerprint(onboarding, template, state, catalog) {
    const input = asObject(onboarding);
    return fingerprint({
      contextKey: contextKey(input),
      boundary: asObject(input.boundary),
      entities: asArray(input.entities),
      changes: asArray(input.changes),
      source: template.source,
      screening: template.screeningId ? asObject(asObject(asObject(state._plan).screening)[template.screeningId]) : null,
      locations: asArray(input.locations),
      catalog: asObject(catalog)
    }, 'upstream-item');
  }

  function reconcileInternal(onboarding, plan, catalog) {
    const input = asObject(onboarding);
    const previous = clone(asObject(plan)) || {};
    const next = {
      ...previous,
      schemaVersion: SCHEMA_VERSION,
      catalogVersion: text(asObject(catalog).version),
      contextKey: contextKey(input),
      onboardingFingerprint: onboardingFingerprint(input),
      items: clone(asObject(previous.items)) || {},
      custom: clone(asArray(previous.custom)),
      screening: screeningSeed(catalog, previous.screening)
    };
    const templates = buildTemplates(input, next, catalog);
    templates.forEach(function (template) {
      const prior = asObject(next.items[template.id]);
      const customSeed = template.custom || {};
      const seed = Object.keys(prior).length ? prior : customSeed;
      const state = baseState(template.id, seed, template.seedLocationIds, template.seedLocationMode);
      state._plan = next;
      const currentFingerprint = itemFingerprint(input, template, state, catalog);
      delete state._plan;

      const validChecks = new Set(mergedChecklist(template.catalog, state.subtypeId).map(function (check) {
        return text(check.id);
      }));
      const filteredChecks = {};
      Object.keys(state.checks).forEach(function (id) {
        if (validChecks.has(id)) filteredChecks[id] = state.checks[id];
      });
      state.checks = filteredChecks;

      const hasWork = state.status !== 'not-started' || state.notes !== '' || state.records.length > 0 || Object.keys(state.checks).length > 0;
      const hasCurrentFingerprint = state.inputFingerprint.startsWith('upstream-item-');
      const migratingLegacyFingerprint = state.inputFingerprint.startsWith('item-');
      const legacyUpstreamChanged = migratingLegacyFingerprint && (
        Boolean(previous.onboardingFingerprint && previous.onboardingFingerprint !== next.onboardingFingerprint) ||
        Boolean(previous.catalogVersion && previous.catalogVersion !== next.catalogVersion)
      );
      const changed = Boolean((hasCurrentFingerprint && state.inputFingerprint !== currentFingerprint) || legacyUpstreamChanged);
      const unversionedWork = !state.inputFingerprint && hasWork;
      if (changed || unversionedWork) {
        state.needsReview = true;
        if (state.status === 'complete') state.status = 'in-progress';
      }
      state.inputFingerprint = currentFingerprint;
      next.items[template.id] = state;
    });
    return next;
  }

  function createPlan(onboarding, catalog) {
    return reconcileInternal(onboarding, {
      schemaVersion: SCHEMA_VERSION,
      catalogVersion: text(asObject(catalog).version),
      contextKey: contextKey(onboarding),
      onboardingFingerprint: onboardingFingerprint(onboarding),
      items: {},
      custom: [],
      screening: {}
    }, catalog);
  }

  function reconcilePlan(onboarding, plan, catalog) {
    const prior = asObject(plan);
    const expectedContext = contextKey(onboarding);
    if (prior.contextKey && prior.contextKey !== expectedContext) {
      const fresh = createPlan(onboarding, catalog);
      if (Array.isArray(prior.archives)) fresh.archives = clone(prior.archives);
      return fresh;
    }
    return reconcileInternal(onboarding, prior, catalog);
  }

  function scopeTitle(scope) {
    return scope === '1' ? 'Scope 1' : scope === '2' ? 'Scope 2' : scope === '3' ? 'Scope 3' : 'Unclassified';
  }

  function upstreamIssues(onboarding) {
    const input = asObject(onboarding);
    const company = asObject(input.company);
    const period = asObject(input.period);
    const boundary = asObject(input.boundary);
    const review = asObject(input.review);
    const issues = [];
    if (!text(company.legal).trim()) issues.push('Reporting company legal name is unanswered.');
    if (!text(company.country).trim()) issues.push('Reporting company country is unanswered.');
    const start = parseDate(text(period.start));
    const end = parseDate(text(period.end));
    if (!start || !end || start > end) issues.push('Reporting period dates are incomplete or invalid and need review.');
    if (!text(boundary.approach).trim() || boundary.approach === 'Not sure') issues.push('Consolidation approach is unanswered or uncertain.');
    if (!text(boundary.operations).trim()) issues.push('Included operations are not yet described.');
    if (['Financial control', 'Equity share'].includes(boundary.approach)) issues.push('The proposed consolidation approach requires authorized boundary review.');

    const locations = asArray(input.locations);
    if (!locations.length) issues.push('No operating locations have been captured; this is not treated as no operations.');
    locations.forEach(function (raw, index) {
      const location = asObject(raw);
      const label = text(location.name).trim() || 'Location ' + (index + 1);
      if (!text(location.id).trim()) issues.push(label + ' has no stable location ID.');
      if (!text(location.included).trim() || location.included === 'Not sure' || text(location.included).startsWith('Exclude')) issues.push(label + ' has an unresolved proposed-boundary decision.');
      if (['Leased', 'Shared', 'Other', 'Not sure'].includes(location.occupancy) || ['Landlord', 'Shared control', 'Other', 'Not sure'].includes(location.control)) issues.push(label + ' has lease or control details that require boundary review.');
      if (location.entity === 'Not sure' || location.entity === 'Other') issues.push(label + ' has an unresolved operating-entity assignment.');
    });
    asArray(input.changes).forEach(function (raw, index) {
      const change = asObject(raw);
      if (change.answer === 'Yes' || change.answer === 'Not sure') {
        issues.push('Boundary change ' + (index + 1) + ' is present or uncertain and requires review.');
        if (!text(change.details).trim()) issues.push('Boundary change ' + (index + 1) + ' needs affected-entity or location details.');
      }
    });
    if (review.complete !== true || review.needed !== true || !text(review.role).trim()) issues.push('Onboarding review acknowledgement or reviewer role is incomplete.');
    return issues;
  }

  function derive(onboarding, plan, catalog) {
    const input = asObject(onboarding);
    const reconciled = reconcilePlan(input, plan, catalog);
    const locationMap = locationsById(input);
    const templates = buildTemplates(input, reconciled, catalog);
    const issues = upstreamIssues(input);
    const items = templates.map(function (template) {
      const state = clone(asObject(reconciled.items[template.id]));
      const savedLocationIds = asArray(state.locationIds).map(text).filter(Boolean);
      const locationMode = VALID_LOCATION_MODES.has(state.locationMode) ? state.locationMode : 'sites';
      const locationIds = locationMode === 'company-wide' ? [] : savedLocationIds;
      const resolvedLocations = locationIds.filter(function (id) { return locationMap.has(id); }).map(function (id) {
        return clone(locationMap.get(id));
      });
      const locations = locationMode === 'company-wide' ? [] : resolvedLocations;
      const orphanLocationIds = locationMode === 'company-wide' ? [] : locationIds.filter(function (id) { return !locationMap.has(id); });
      const subtypeId = text(state.subtypeId);
      const subtypeValid = !subtypeId || asArray(template.catalog.subtypes).some(function (entry) {
        return text(asObject(entry).id) === subtypeId;
      });
      const checklist = mergedChecklist(template.catalog, subtypeId);
      const unassigned = locationMode === 'company-wide' ? false : locationMode === 'unknown' || locations.length === 0;
      if (unassigned) issues.push(scopeTitle(template.scope) + ' item "' + template.catalog.title + '" has unresolved location coverage.');
      if (orphanLocationIds.length) issues.push(scopeTitle(template.scope) + ' item "' + template.catalog.title + '" references a removed location and needs review.');
      if (!subtypeValid) issues.push(scopeTitle(template.scope) + ' item "' + template.catalog.title + '" has an unavailable subtype and needs review.');
      if ((template.kind === 'inventory' || template.kind === 'custom') && asArray(template.catalog.subtypes).length && !subtypeId) issues.push(scopeTitle(template.scope) + ' item "' + template.catalog.title + '" needs a subtype or explicit other/unknown selection.');
      const unchecked = checklist.filter(function (check) { return state.checks[text(check.id)] !== true; });
      if ((template.kind === 'inventory' || template.kind === 'custom') && unchecked.length) issues.push(scopeTitle(template.scope) + ' item "' + template.catalog.title + '" has ' + unchecked.length + ' unfinished collection step' + (unchecked.length === 1 ? '.' : 's.'));
      if ((template.kind === 'inventory' || template.kind === 'custom') && state.status !== 'complete') issues.push(scopeTitle(template.scope) + ' item "' + template.catalog.title + '" still needs method and collection review.');
      if ((template.kind === 'inventory' || template.kind === 'custom') && !asArray(state.records).length) issues.push(scopeTitle(template.scope) + ' item "' + template.catalog.title + '" has no activity records yet.');
      if (state.needsReview === true) issues.push(scopeTitle(template.scope) + ' item "' + template.catalog.title + '" changed and needs renewed review.');
      asArray(state.records).forEach(function (record, index) {
        const recordLabel = 'Record ' + (index + 1) + ' for "' + template.catalog.title + '"';
        validateRecord(record, input).forEach(function (error) { issues.push(recordLabel + ': ' + error); });
        if (asObject(record).quantity == null || asObject(record).quantity === '') issues.push(recordLabel + ' has no quantity and remains incomplete.');
        if (!text(asObject(record).reference).trim()) issues.push(recordLabel + ' has no evidence reference.');
      });
      if (template.kind === 'custom' && (template.scope === 'unknown' || !template.familyId)) issues.push('Custom item "' + template.catalog.title + '" still needs scope or source-family classification.');
      return {
        id: template.id,
        scope: template.scope,
        familyId: template.familyId || '',
        screeningId: template.screeningId || '',
        customId: template.customId || '',
        ...catalogTemplateFields(template.catalog),
        checklist: checklist,
        answer: template.answer,
        kind: template.kind,
        source: template.source ? clone(template.source) : null,
        names: template.source ? text(template.source.names) : '',
        sourceNames: template.source ? text(template.source.names) : '',
        sourceNotes: template.source ? text(template.source.notes) : '',
        status: state.status,
        needsReview: state.needsReview === true,
        inputFingerprint: text(state.inputFingerprint),
        subtypeId: subtypeId,
        subtypeValid: subtypeValid,
        locationMode: locationMode,
        locationIds: locationIds,
        retainedLocationIds: locationMode === 'company-wide' ? savedLocationIds : [],
        locations: locations,
        orphanLocationIds: orphanLocationIds,
        unassigned: unassigned,
        checks: clone(asObject(state.checks)) || {},
        notes: text(state.notes),
        records: clone(asArray(state.records))
      };
    });

    const exclusions = [];
    familyCatalog(catalog).forEach(function (family, index) {
      const source = asObject(asArray(input.sources)[index]);
      const answer = normalizeAnswer(source.answer);
      const scope1Screening = asObject(reconciled.screening['scope1:' + family.id]);
      const reason = text(scope1Screening.reason || source.notes);
      if (answer === '') issues.push('Scope 1 screening "' + family.title + '" is unanswered.');
      if (answer === 'Not sure') issues.push('Scope 1 screening "' + family.title + '" is uncertain and needs clarification.');
      if (answer === 'Yes' && !text(source.names).trim()) issues.push('Scope 1 source "' + family.title + '" needs equipment or activity names.');
      if (answer === 'No') {
        exclusions.push({
          id: 'scope1:' + family.id,
          scope: '1',
          title: family.title,
          answer: 'No',
          reason: reason,
          notes: text(source.notes),
          retainedState: Boolean(asObject(reconciled.items)['scope1:' + family.id])
        });
        if (!reason.trim()) issues.push('Scope 1 screening "' + family.title + '" is No but has no rationale.');
      }
    });

    const screening = [];
    ['2', '3'].forEach(function (scope) {
      scopeCatalog(catalog, scope).forEach(function (entry) {
        const state = clone(asObject(reconciled.screening[entry.id]));
        const answer = normalizeAnswer(state.answer);
        const itemId = 'scope' + scope + ':' + entry.id;
        const view = {
          id: entry.id,
          itemId: itemId,
          scope: scope,
          ...catalogTemplateFields(entry),
          answer: answer,
          reason: text(state.reason),
          notes: text(state.notes),
          locationIds: asArray(state.locationIds).map(text).filter(Boolean),
          locationMode: VALID_LOCATION_MODES.has(state.locationMode) ? state.locationMode : 'sites'
        };
        screening.push(view);
        if (answer === '') issues.push(scopeTitle(scope) + ' screening "' + entry.title + '" is unanswered.');
        if (answer === 'Not sure') issues.push(scopeTitle(scope) + ' screening "' + entry.title + '" is uncertain and needs clarification.');
        if (answer === 'No') {
          exclusions.push({
            id: itemId,
            screeningId: entry.id,
            scope: scope,
            title: entry.title,
            answer: 'No',
            reason: view.reason,
            notes: view.notes,
            retainedState: Boolean(asObject(reconciled.items)[itemId])
          });
          if (!view.reason.trim()) issues.push(scopeTitle(scope) + ' screening "' + entry.title + '" is No but has no rationale.');
        }
      });
    });

    asArray(reconciled.custom).forEach(function (custom, index) {
      if (!text(asObject(custom).id)) issues.push('Custom item ' + (index + 1) + ' needs a stable ID before it can be reconciled safely.');
    });

    return {
      schemaVersion: SCHEMA_VERSION,
      catalogVersion: text(asObject(catalog).version),
      contextKey: reconciled.contextKey,
      onboardingFingerprint: reconciled.onboardingFingerprint,
      company: clone(asObject(input.company)),
      period: clone(asObject(input.period)),
      locations: clone(asArray(input.locations)),
      items: items,
      exclusions: exclusions,
      screening: screening,
      unassigned: items.filter(function (item) { return item.unassigned; }).map(function (item) { return item.id; }),
      issues: issues,
      plan: reconciled
    };
  }

  function parseDate(value) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
    const parts = value.split('-').map(Number);
    const date = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2]));
    if (date.getUTCFullYear() !== parts[0] || date.getUTCMonth() !== parts[1] - 1 || date.getUTCDate() !== parts[2]) return null;
    return value;
  }

  function validateRecord(record, onboarding) {
    const value = asObject(record);
    const errors = [];
    const quantity = value.quantity;
    if (quantity != null && quantity !== '') {
      if (!normalizeQuantity(quantity).valid) {
        errors.push('Quantity must be a nonnegative decimal. Use commas only as thousands separators, such as 1,234.50.');
      }
    }
    if (!text(value.recordType).trim()) errors.push('Record type is required.');
    if (!text(value.unit).trim()) errors.push('Unit is required.');
    if (!VALID_QUALITIES.has(value.quality)) errors.push('Quality must be actual, estimated or unknown.');
    if (Object.prototype.hasOwnProperty.call(value, 'fuelType') && !VALID_RECORD_FUEL_TYPES.has(text(value.fuelType))) errors.push('Fuel for this record is invalid.');

    const start = text(value.periodStart);
    const end = text(value.periodEnd);
    const validStart = parseDate(start);
    const validEnd = parseDate(end);
    if (!validStart) errors.push('Record period start must be a valid YYYY-MM-DD date.');
    if (!validEnd) errors.push('Record period end must be a valid YYYY-MM-DD date.');
    if (validStart && validEnd && validStart > validEnd) errors.push('Record period end must be on or after its start.');

    const reporting = asObject(asObject(onboarding).period);
    const reportingStart = parseDate(text(reporting.start));
    const reportingEnd = parseDate(text(reporting.end));
    if (!reportingStart || !reportingEnd || reportingStart > reportingEnd) {
      errors.push('A valid reporting period is required to validate record dates.');
    } else {
      if (validStart && (validStart < reportingStart || validStart > reportingEnd)) errors.push('Record period start must fall within the reporting period.');
      if (validEnd && (validEnd < reportingStart || validEnd > reportingEnd)) errors.push('Record period end must fall within the reporting period.');
    }
    return errors;
  }

  function normalizeQuantity(value) {
    if (value == null || value === '') return { original: value, canonical: value, valid: true };
    if (typeof value !== 'string') return { original: value, canonical: value, valid: false };
    const original = value;
    const trimmed = value.trim();
    const plain = /^\d+(?:\.\d+)?$/.test(trimmed);
    const grouped = /^\d{1,3}(?:,\d{3})+(?:\.\d+)?$/.test(trimmed);
    return { original: original, canonical: plain || grouped ? trimmed.replace(/,/g, '') : trimmed, valid: plain || grouped };
  }

  function normalizeUnit(value) {
    const original = text(value);
    const trimmed = original.trim();
    const canonical = UNIT_ALIASES[trimmed.toLowerCase()] || trimmed;
    return { original: original, canonical: canonical, changed: canonical !== original };
  }

  function inferLegacyFuelType(value) {
    const label = text(value).trim().toLowerCase().replace(/[\s_-]+/g, ' ');
    const match = label.match(/^(natural gas|gasoline|diesel|propane|fuel oil)(?: (?:bill|bills|purchase|purchases|purchased|consumed|consumption|use|usage|fuel))?$/);
    return match ? {'natural gas':'natural-gas','fuel oil':'fuel-oil'}[match[1]] || match[1] : '';
  }

  function selectRecordFuel(record, fuelType) {
    const selected = clone(asObject(record)) || {};
    if (!VALID_RECORD_FUEL_TYPES.has(text(fuelType))) return selected;
    selected.fuelType = text(fuelType);
    selected.fuelTypeSource = 'user';
    return selected;
  }

  function normalizeRecord(record) {
    const normalized = clone(asObject(record)) || {};
    const quantity = normalizeQuantity(normalized.quantity);
    const unit = normalizeUnit(normalized.unit);
    if (quantity.valid) {
      if (quantity.canonical !== quantity.original) normalized.quantityOriginal = quantity.original;
      else if (Object.prototype.hasOwnProperty.call(normalized, 'quantityOriginal') && normalizeQuantity(normalized.quantityOriginal).canonical !== quantity.canonical) delete normalized.quantityOriginal;
      normalized.quantity = quantity.canonical;
    }
    if (unit.canonical !== unit.original) normalized.unitOriginal = unit.original;
    else if (Object.prototype.hasOwnProperty.call(normalized, 'unitOriginal') && normalizeUnit(normalized.unitOriginal).canonical !== unit.canonical) delete normalized.unitOriginal;
    normalized.unit = unit.canonical;
    if (!Object.prototype.hasOwnProperty.call(normalized, 'fuelType')) {
      const legacyFuel = inferLegacyFuelType(normalized.recordType);
      if (legacyFuel) {
        normalized.fuelType = legacyFuel;
        normalized.fuelTypeSource = 'legacy-record-type';
      }
    }
    return normalized;
  }

  function escapeHtml(value) {
    return text(value).replace(/[&<>"']/g, function (character) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character];
    });
  }

  return Object.freeze({
    SCHEMA_VERSION: SCHEMA_VERSION,
    SOURCE_FAMILY_IDS: Object.freeze(SOURCE_FAMILY_IDS.slice()),
    RECORD_FUEL_TYPES: RECORD_FUEL_TYPES,
    createPlan: createPlan,
    onboardingFingerprint: onboardingFingerprint,
    fingerprintOnboarding: onboardingFingerprint,
    reconcilePlan: reconcilePlan,
    reconcile: reconcilePlan,
    derive: derive,
    validateRecord: validateRecord,
    normalizeQuantity: normalizeQuantity,
    normalizeUnit: normalizeUnit,
    inferLegacyFuelType: inferLegacyFuelType,
    selectRecordFuel: selectRecordFuel,
    normalizeRecord: normalizeRecord,
    escapeHtml: escapeHtml
  });
});

'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const vm = require('node:vm');
const PlanCore = require('./plan-core.js');

const catalogPath = path.join(__dirname, 'data', 'collection-catalog.json');
const catalog = JSON.parse(fs.readFileSync(catalogPath, 'utf8'));

function onboarding(overrides = {}) {
  return {
    company: { legal: 'Example Co', country: 'United States', industry: 'Bakery', ...(overrides.company || {}) },
    period: { start: '2025-01-01', end: '2025-12-31', first: 'Yes', ...(overrides.period || {}) },
    boundary: { approach: 'Operational control' },
    entities: [],
    locations: [{ id: 'loc-1', name: 'Main site', included: 'Include' }, { id: 'loc-2', name: 'Warehouse', included: 'Include' }],
    changes: Array.from({ length: 5 }, () => ({ answer: 'No' })),
    sources: Array.from({ length: 5 }, () => ({ answer: 'No' })),
    review: {},
    ...overrides,
    company: { legal: 'Example Co', country: 'United States', industry: 'Bakery', ...(overrides.company || {}) },
    period: { start: '2025-01-01', end: '2025-12-31', first: 'Yes', ...(overrides.period || {}) }
  };
}

