test('file selection, in-flight upload and orphan recovery have explicit UI guards', () => {
  const ui = fs.readFileSync(path.join(ROOT, 'plan-ui.js'), 'utf8');
  assert.match(ui, /if\(uploading\|\|\$\('#evidenceFile'\)\.files\.length\)/);
